extends RefCounted

const INDEX_BITS = 32
const INDEX_MASK = (1 << INDEX_BITS) - 1
const GENERATION_SHIFT = INDEX_BITS

var _generations: PackedInt32Array
var _free_indices: PackedInt32Array
var _slot_archetype: Dictionary # index -> Archetype
var _archetypes: Dictionary      # _signature(types) -> Archetype

class Archetype:
	extends RefCounted
	var types: PackedStringArray
	var entities: Dictionary # index -> Dictionary{component_type: data}

	func _init(t: PackedStringArray):
		types = t
		entities = {}

func _init():
	_generations = PackedInt32Array()
	_free_indices = PackedInt32Array()
	_slot_archetype = {}
	_archetypes = {}
	_ensure_archetype(PackedStringArray())

func _encode(index: int, gen: int) -> int:
	return (gen << GENERATION_SHIFT) | (index & INDEX_MASK)

func get_index(entity: int) -> int:
	return entity & INDEX_MASK

func get_generation(entity: int) -> int:
	return (entity >> GENERATION_SHIFT) & INDEX_MASK

func _is_index_alive(index: int) -> bool:
	return index >= 0 and index < _generations.size() and _slot_archetype.has(index)

func is_alive(entity: int) -> bool:
	var index = get_index(entity)
	if not _is_index_alive(index):
		return false
	return get_generation(entity) == _generations[index]

func create_entity() -> int:
	var index: int
	var gen: int
	if _free_indices.size() > 0:
		index = _free_indices[ _free_indices.size() - 1 ]
		_free_indices.remove_at(_free_indices.size() - 1)
		gen = _generations[index] + 1
	else:
		index = _generations.size()
		_generations.append(1)
		gen = 1
	_generations[index] = gen
	var archetype = _ensure_archetype(PackedStringArray())
	archetype.entities[index] = {}
	_slot_archetype[index] = archetype
	return _encode(index, gen)

func destroy_entity(entity: int) -> bool:
	if not is_alive(entity):
		return false
	var index = get_index(entity)
	var archetype = _slot_archetype[index]
	archetype.entities.erase(index)
	_slot_archetype.erase(index)
	_free_indices.append(index)
	return true

func add_component(entity: int, component_type: StringName, data: Dictionary) -> bool:
	if not is_alive(entity):
		return false
	var index = get_index(entity)
	var archetype = _slot_archetype[index]
	if archetype.types.has(component_type):
		archetype.entities[index][component_type] = data
		return true
	var new_types = archetype.types.duplicate()
	new_types.append(component_type)
	new_types.sort()
	var new_archetype = _ensure_archetype(new_types)
	new_archetype.entities[index] = archetype.entities[index].duplicate()
	new_archetype.entities[index][component_type] = data
	archetype.entities.erase(index)
	_slot_archetype[index] = new_archetype
	return true

func remove_component(entity: int, component_type: StringName) -> bool:
	if not is_alive(entity):
		return false
	var index = get_index(entity)
	var archetype = _slot_archetype[index]
	if not archetype.types.has(component_type):
		return false
	var new_types = PackedStringArray()
	for t in archetype.types:
		if t != component_type:
			new_types.append(t)
	var new_archetype = _ensure_archetype(new_types)
	var new_data = archetype.entities[index].duplicate()
	new_data.erase(component_type)
	new_archetype.entities[index] = new_data
	archetype.entities.erase(index)
	_slot_archetype[index] = new_archetype
	return true

func has_component(entity: int, component_type: StringName) -> bool:
	if not is_alive(entity):
		return false
	return _slot_archetype[get_index(entity)].types.has(component_type)

func get_component(entity: int, component_type: StringName) -> Variant:
	if not is_alive(entity):
		return null
	var archetype = _slot_archetype[get_index(entity)]
	return archetype.entities[get_index(entity)].get(component_type)

func get_component_types(entity: int) -> Variant:
	if not is_alive(entity):
		return null
	return Array(_slot_archetype[get_index(entity)].types)

func _ensure_archetype(types: PackedStringArray) -> Archetype:
	var sig = _archetype_signature(types)
	if not _archetypes.has(sig):
		var arch = Archetype.new(types)
		_archetypes[sig] = arch
	return _archetypes[sig]

func _archetype_signature(types: PackedStringArray) -> String:
	return ",".join(types)

func _sorted_archetype_types(types: Array) -> PackedStringArray:
	var sa = PackedStringArray()
	for t in types:
		sa.append(t as StringName)
	sa.sort()
	return sa

func query(required_types: Array) -> Array:
	var req = _sorted_archetype_types(required_types)
	var result = []
	for index in _slot_archetype:
		var arch = _slot_archetype[index]
		if _has_supersets(arch.types, req):
			result.append(_encode(index, _generations[index]))
	result.sort()
	return result

func get_entities_with_exact_types(types: Array) -> Array:
	var req = _sorted_archetype_types(types)
	var sig = _archetype_signature(req)
	var arch = _archetypes.get(sig)
	if not arch:
		return []
	var result = []
	for index in arch.entities:
		result.append(_encode(index, _generations[index]))
	result.sort()
	return result

func _has_supersets(types: PackedStringArray, required: PackedStringArray) -> bool:
	if required.size() == 0:
		return true
	for r in required:
		if not types.has(r):
			return false
	return true

