		return true
	var new_types = archetype.types.duplicate()
	new_types.append(component_type)
	new_types.sort()
	var new_archetype = _ensure_archetype(new_types)
	new_archetype.entities[index] = archetype.entities[index].duplicate()
	new_archetype.entities[index][component_type] = data
	archetype.entities.erase(index)
	_slot_archetype[index] = new_archetype
