func get_component_types(entity: int) -> Variant:
	if not is_alive(entity):
		return null
	return Array(_slot_archetype[get_index(entity)].types)

func _sorted_archetype_types(types: Array) -> PackedStringArray:
	var sa = PackedStringArray()
	for t in types:
		sa.append(t as StringName)
	sa.sort()
	return sa

## Get or create the Archetype for a type set (sorted Array required).
func _ensure_archetype(sorted_types: PackedStringArray) -> Archetype:
	var node = _archetypes_trie
	for t in sorted_types:
		if not node.has(t):
			node[t] = {}
		node = node[t]
	if not node.has("__arch"):
		node["__arch"] = Archetype.new(sorted_types)
	return node["__arch"]

func query(required_types: Array) -> Array:
	var req = _sorted_archetype_types(required_types)
	var result = []
	for index in _slot_archetype:
		var arch = _slot_archetype[index]
		if _has_supersets(arch.types, req):
			result.append(_encode(index, _generations[index]))
	result.sort()
	return result

func get_entities_with_exact_types(types: Array) -> Array:
	var req = _sorted_archetype_types(types)
	var arch = _find_archetype(req)
	if not arch:
		return []
	var result = []
	for index in arch.entities:
		result.append(_encode(index, _generations[index]))
	result.sort()
	return result

func _find_archetype(sorted_types: PackedStringArray) -> Variant:
	var node = _archetypes_trie
	for t in sorted_types:
		if not node.has(t):
			return null
		node = node[t]
	return node.get("__arch")

func _has_supersets(types: PackedStringArray, required: PackedStringArray) -> bool:
	if required.size() == 0:
		return true
	if required.size() > types.size():
		return false
	var i = 0; var j = 0
	while i < required.size() and j < types.size():
		if required[i] == types[j]:
			i += 1; j += 1
		elif required[i] < types[j]:
			return false
		else:
			j += 1
	return i == required.size()

